// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address baseTokenParam, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        vm.assume(caller != baseTokenParam);
        vm.assume(feeRate <= 5_000);
        vm.prank(caller);
        c.initialize(baseTokenParam, address(0x1234), vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties);
        assertTrue(c.baseToken() == baseTokenParam);
    }
}
